class Solution:
    def floodFill(self, image: List[List[int]], sr: int, sc: int, color: int) -> List[List[int]]:
        orig_color = image[sr][sc]
        if orig_color == color:
            return image
        m, n = len(image), len(image[0])
        def dfs(r: int, c: int):
            if r < 0 or r >= m or c < 0 or c >= n or image[r][c] != orig_color:
                return
            image[r][c] = color
            dfs(r + 1, c)
            dfs(r - 1, c)
            dfs(r, c + 1)
            dfs(r, c - 1)
        dfs(sr, sc)
        return image

class Solution {
public:
    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {
        int origColor = image[sr][sc];
        if (origColor == color) return image;
        int m = image.size(), n = image[0].size();
        auto dfs = [&](auto& self, int r, int c) -> void {
            if (r < 0 || r >= m || c < 0 || c >= n || image[r][c] != origColor) return;
            image[r][c] = color;
            self(self, r + 1, c);
            self(self, r - 1, c);
            self(self, r, c + 1);
            self(self, r, c - 1);
        };
        dfs(dfs, sr, sc);
        return image;
    }
};

class Solution {
    public int[][] floodFill(int[][] image, int sr, int sc, int color) {
        int origColor = image[sr][sc];
        if (origColor == color) return image;
        dfs(image, sr, sc, origColor, color);
        return image;
    }
    private void dfs(int[][] img, int r, int c, int orig, int color) {
        if (r < 0 || r >= img.length || c < 0 || c >= img[0].length || img[r][c] != orig) return;
        img[r][c] = color;
        dfs(img, r + 1, c, orig, color);
        dfs(img, r - 1, c, orig, color);
        dfs(img, r, c + 1, orig, color);
        dfs(img, r, c - 1, orig, color);
    }
}

var floodFill = function(image, sr, sc, color) {
    const origColor = image[sr][sc];
    if (origColor === color) return image;
    const m = image.length, n = image[0].length;
    function dfs(r, c) {
        if (r < 0 || r >= m || c < 0 || c >= n || image[r][c] !== origColor) return;
        image[r][c] = color;
        dfs(r + 1, c);
        dfs(r - 1, c);
        dfs(r, c + 1);
        dfs(r, c - 1);
    }
    dfs(sr, sc);
    return image;
};
